// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val, uint256 _lockTime, uint256 _am, uint256 _msgValue) public {
        // Restrict inputs to valid range
        vm.assume(_lockTime < 1e12);
        vm.assume(_am < 1e12);
        vm.assume(_msgValue < 1e12);
        vm.assume(_val < 1e12);

        // Initialize the contract: set MinSum, then finalize initialization
        c.SetMinSum(_val);
        c.Initialized();

        // The buggy version would change MinSum in SetMinSum, but we already set it
        // Now call Collect after potentially putting some funds
        address user = address(0x1234);
        vm.deal(user, _msgValue);
        vm.prank(user);
        address(c).call{value: _msgValue}("");

        vm.prank(user);
        // Try to collect; may revert if conditions not met
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", _am));

        // The rule: after any call to Collect, MinSum equals the initial value set
        assertTrue(c.MinSum() == _val, "MinSum should remain unchanged after Collect");
    }
}

